// Replicate high-fanout operand
reg [39:0] operand_a, operand_b;
always @(*) {
  operand_a = source;
  operand_b = source;
}
wire prod1 = multiply(operand_a, factor1);
wire prod2 = multiply(operand_b, factor2);

// Before: two carries + output selection
wire [N-1:0] sum_a = a + b;
wire [N-1:0] sum_b = c + d;
assign result = select ? sum_a : sum_b;

// After: input mux + one carry
wire [N-1:0] a_sel = select ? a : c;
wire [N-1:0] b_sel = select ? b : d;
assign result = a_sel + b_sel;

// Before:
always @(*) begin
  sat_val = (s3 > SAT_MAX) ? SAT_MAX : s3;
  sat_flag = (s3 > SAT_MAX) || (s3 < SAT_MIN);
end

// After:
// Remove SAT_MAX, SAT_MIN, LIMIT params; sat_flag always 0; assign sat_val = s3;

// Carry-lookahead applied internally, but mux gates both carries
wire [N-1:0] cla_sum = carry_lookahead_adder(a, b);
wire [N-1:0] other_sum = other_adder(c, d);
assign result = select ? cla_sum : other_sum; // mux still critical

// depth 3
wire [W:0] s = ((a + b) + c) + d;
// depth 2, same value
wire [W:0] s = (a + b) + (c + d);

// Tree: (s0+s1, s2+s3) then their sum
sum_01 = s0 + s1;
sum_23 = s2 + s3;
result = sum_01 + sum_23; // depth 2

// Carry-save attempt:
compressor_3to2(s0, s1, s2, s3, sum, carry);
result = sum + carry; // still high latency from final add

// INEFFECTIVE: inlined
assign sum = {s0[39], s0} + {s1[39], s1} + {s2[39], s2};

// BETTER: decomposed
wire [39:0] s0_ext = {{8{prod0[31]}}, prod0};
wire [39:0] s1_ext = {{8{prod1[31]}}, prod1};
assign sum = s0_ext + s1_ext + s2_ext;

// binary state, decoded late
assign en = (state == RUN);
// one-hot, decoded early
always @(posedge clk) en_q <= (next_state == RUN);

// Carry-save strategy (breaks equivalence):
// sum1, carry1 = CSA_32(a, b, c)  // constant depth
// sum2, carry2 = CSA_32(sum1, carry1, d)
// result = sum2 + carry2  // one ripple
// Problem: breaks if accumulator logic expects specific bit-by-bit propagation order

// depth N
for (i = N-1; i >= 0; i = i - 1)
  assign h[i] = r[i] | h[i+1];
// depth ceil(log2 N)
assign any = |r;

// depth 3
assign y = a ? p : b ? q : c ? r : s;
// depth 1 mux tree
always @(*) case (1'b1) a: y=p; b: y=q; c: y=r; default: y=s; endcase

// in the path
always @(posedge clk) q <= rst ? 0 : (a + b);
// on the reset port
always @(posedge clk or negedge rst_n)
  if (!rst_n) q <= 0; else q <= a + b;

// serial
assign y = (s > MAX) ? MAX : (s < MIN) ? MIN : s;
// condition formed from overflow bits available early

// before: select, then compute
wire [W-1:0] op = fwd ? ex_result : rf_data;
wire [W-1:0] y  = op + b;
// after: compute both, select last
wire [W-1:0] y0 = rf_data   + b;
wire [W-1:0] y1 = ex_result + b;
wire [W-1:0] y  = fwd ? y1 : y0;

// wide adds
wire [39:0] s = {{8{p0[31]}},p0} + {{8{p1[31]}},p1};
// narrow add, one extension
wire [32:0] t = p0 + p1;

// serial: sum, then compare
wire over = (sum > LIMIT);
// parallel: the top bits already decide it
wire over = |sum[W-1:LIMIT_BITS] & ~sum[W-1];
